export function providerFit(provider) {
  return {
    suitable: provider.specialty,
    responsibility: provider.mode==='multi' ? '全程组织；需逐段确认承运与交接责任' : provider.mode==='water' ? '水路干线；两端接驳另行核对' : provider.mode==='rail' ? '铁路段及交接协同；短驳范围另议' : provider.mode==='air' ? '指定服务点之间配送；先核验承接条件' : '约定装卸地点间运输；仓配服务分别约定',
    reviewNote: provider.reviewCount ? `${provider.reviewCount}条企业服务评价；不等于本单履约保证` : '暂无评价，建议先核对承接范围与费用',
  }
}
